'use server'

import { updateTag } from 'next/cache'

// Replace this with your real data layer (database, API, etc.).
// The posts list is cached and tagged with 'posts' (e.g. via
// `cacheTag('posts')` in a `'use cache'` function, or
// `fetch(url, { next: { tags: ['posts'] } })`).
async function savePost(data: { title: string; content: string }) {
  // await db.post.create({ data })
  return { id: crypto.randomUUID(), ...data }
}

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '')
  const content = String(formData.get('content') ?? '')

  const post = await savePost({ title, content })

  // Invalidate the 'posts' cache tag.
  //
  // We use `updateTag` (not `revalidateTag`) deliberately: `revalidateTag`
  // uses stale-while-revalidate semantics and would serve the OLD cached
  // posts list on the next load while fresh data is fetched in the
  // background. `updateTag` expires the tag immediately, so the next request
  // blocks until fresh data is fetched — guaranteeing the user never sees
  // stale content after creating a post (read-your-own-writes).
  updateTag('posts')

  return post
}

